const REACT_VERSION = React.version;

ReactDOM.render(
  <div>{`React version: ${REACT_VERSION}`}</div>,
  document.getElementById("app")
);
```

代码拆分是 Webpack、Browserify 等打包工具支持的功能，可以生成多个在运行时动态加载的代码包。React 项目可以通过动态 import() 实现代码拆分。

例如，下面的代码会将 moduleA.js 及其独有的依赖拆成单独的代码块，只有用户点击“加载”按钮后才加载。

**moduleA.js**

```javascript
const moduleA = "Hello";

export { moduleA };
```

**App.js**

```javascript
export default function App {
  function handleClick() {
    import("./moduleA")
      .then(({ moduleA }) => {
        // Use moduleA
      })
      .catch((err) => {
        // Handle failure
      });
  };

 return (
   <div>
     <button onClick={this.handleClick}>Load</button>
   </div>
 );
}
```

